function mirror(n) {
  if (n === 0) {
    return "|";
  }

  return n + mirror(n - 1) + n;
}

function ways(steps) {
  if (steps <= 1) {
    return 1;
  }

  return ways(steps - 1) + ways(steps - 2);
}

console.log(mirror(0));
console.log(mirror(3));
console.log(ways(1));
console.log(ways(4));
